// src/components/Navbar.js
import React from "react";

export default function Navbar() {
  return (
    <nav className="bg-blue-600 text-white px-6 py-3 flex justify-between items-center shadow-md">
      <h1 className="text-2xl font-bold tracking-wide">AI Interview Coach</h1>
      <div className="space-x-6">
        <a href="#" className="hover:text-gray-200 transition">Home</a>
        <a href="#" className="hover:text-gray-200 transition">Interview</a>
        <a href="#" className="hover:text-gray-200 transition">Feedback</a>
      </div>
    </nav>
  );
}
